Set-Location $PSScriptRoot;
$pathingBackToRepoRoot = "{PathingBackToRepoRoot}";
$pathingBackToDevDriveSetupFolder = "$($pathingBackToRepoRoot)Dev-Drive\Setup";
# . "$($pathingBackToDevDriveSetupFolder)\setup-new-project.ps1"
# . "$($pathingBackToDevDriveSetupFolder)\setup-after-newproject.ps1"
$NewProjectPath = "$($pathingBackToDevDriveSetupFolder)\setup-new-project.ps1"
if (Test-Path -LiteralPath $NewProjectPath -PathType Leaf) {
    . $NewProjectPath
}
else {
    Write-Error "setup-new-project.ps1 not found at '$NewProjectPath'."
    exit;
}
$AfterProjectPath = "$($pathingBackToDevDriveSetupFolder)\setup-after-newproject.ps1"
if (Test-Path -LiteralPath $AfterProjectPath -PathType Leaf) {
    . $AfterProjectPath
}
else {
    Write-Error "setup-after-newproject.ps1 not found at '$AfterProjectPath'."
    exit;
}
